def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    def count_opp(start, end, action):
        c = 0
        for i in range(start, end):
            if opp(i) == action:
                c += 1
        return c

    def count_me(start, end, action):
        c = 0
        for i in range(start, end):
            if me(i) == action:
                c += 1
        return c

    opp_last = opp(n - 1)
    me_last = me(n - 1)

    # Always defect in the last few rounds if we're not clearly behind.
    if n >= 97:
        my_total = 0
        opp_total = 0
        for i in range(n):
            a = me(i)
            b = opp(i)
            if a == 'C' and b == 'C':
                my_total += 3
                opp_total += 3
            elif a == 'C' and b == 'D':
                my_total += 0
                opp_total += 5
            elif a == 'D' and b == 'C':
                my_total += 5
                opp_total += 0
            else:
                my_total += 1
                opp_total += 1
        if my_total >= opp_total - 2:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Detect extremely cooperative opponent
    opp_C = count_opp(0, n, 'C')
    if n >= 10 and opp_C == n:
        # They always cooperate; exploit but occasionally give C to seem nice early
        if n < 15:
            return 'C'
        return 'D'

    # Detect extremely defective opponent
    if n >= 6 and opp_C == 0:
        return 'D'

    # Tit-for-tat with slight forgiveness and retaliation
    if opp_last == 'C':
        # Cooperate preferentially, but if we've been defecting a lot recently, mix
        recent_me_D = count_me(max(0, n - 5), n, 'D')
        if recent_me_D >= 4:
            return 'C'
        return 'C'
    else:
        # Opponent just defected. Retaliate unless pattern suggests forgiveness helps.
        # Count mutual defection streaks
        dd_streak = 0
        i = n - 1
        while i >= 0 and opp(i) == 'D':
            dd_streak += 1
            i -= 1
        if dd_streak >= 3:
            # Long defection war; try to break with cooperation sometimes
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # Standard retaliation
        if rng.random() < 0.9:
            return 'D'
        return 'C'

